"""2.0 story chains: The Lost Library (Hellas), The Palace Examination (Tianxia) and Iron Revolution (Albion).

Same shape as the 1.0 chains: five steps, a relic from a story site, a final choice, an artifact and a capstone tradition.
"""
from heirs_c_chains import F, item, option, step, things, usable
from heirs_data import add
from heirs_kit import research
from heirs_xml import Def, T

# ------------------------------------------------------------------ relics found at the story sites
SCROLLS = item("HE_Hellas_LibraryScrolls", "sealed library scrolls", "mühürlü kütüphane tomarları",
               "A cedar chest of scrolls from the lost library of the Argo, sealed in wax for two centuries. Inside, among the books, lies a small bronze aegis.",
               "Argo'nun kayıp kütüphanesinden, iki yüzyıldır balmumuyla mühürlü tomarlarla dolu bir sedir sandık. İçinde, kitapların arasında küçük bronz bir aegis duruyor.",
               "relic", 800, 3, "HE_Hellas", pargs={"kind": "scroll"}, beauty=8)
JADE_SEAL = item("HE_Tianxia_JadeSeal", "cracked jade seal", "çatlak yeşim mühür",
                 "The imperial seal of Tianxia, carved from a single block of green jade with a coiled dragon on top. A crack runs through one corner. Whoever stamps an edict with it speaks for heaven.",
                 "Tek bir yeşil yeşim bloğundan oyulmuş, tepesinde kıvrılmış bir ejder olan Tianxia imparatorluk mührü. Bir köşesinden bir çatlak geçiyor. Onunla bir fermanı mühürleyen göğün adına konuşur.",
                 "relic", 800, 2, "HE_Tianxia", pargs={"kind": "jade"}, beauty=12)
OLD_DRUM = item("HE_Albion_DentedDrum", "dented regimental drum", "ezik alay davulu",
                "The drum of the Avalon Guard, which beat the first regiment ashore. Its brass is dented and its skin split, but the painted lion can still be made out.",
                "İlk alayı karaya çıkaran Avalon Muhafızları'nın davulu. Pirinci ezilmiş, derisi yarılmış, ama boyalı aslan hâlâ seçilebiliyor.",
                "relic", 800, 3, "HE_Albion", pargs={"kind": "drum"}, beauty=6)

# ------------------------------------------------------------------ artifacts
AEGIS = item("HE_Hellas_Artifact_Aegis", "Owl Aegis", "Baykuş Aegisi",
             "A bronze shield-cloak bearing the owl of wisdom, found among the scrolls of the lost library. Raised high, it steadies friends and sends many enemies running. It must rest for ten days between uses.",
             "Kayıp kütüphanenin tomarları arasında bulunan, bilgelik baykuşunu taşıyan bronz bir kalkan-pelerin. Yukarı kaldırıldığında dostları güçlendirir ve birçok düşmanı kaçırır. Her kullanımdan sonra on gün dinlenmesi gerekir.",
             "owl_aegis", 3500, 3, "HE_Hellas", comps=usable("Raise the aegis", "Aegisi kaldır", flee=0.3, cooldown=10, sound="HE_Sound_Bugle"), beauty=25)
DRAGON_SEAL = item("HE_Tianxia_Artifact_DragonSeal", "Dragon Seal", "Ejder Mührü",
                   "The jade seal, mended with gold. When it is stamped on a war edict, your people take heart, some enemies lose theirs and clouds gather into a gentle rain. It must rest for eleven days between uses.",
                   "Altınla onarılmış yeşim mühür. Bir savaş fermanına basıldığında halkın cesaret bulur, bazı düşmanlar cesaretini yitirir ve bulutlar yumuşak bir yağmura dönüşür. Her kullanımdan sonra on bir gün dinlenmesi gerekir.",
                   "dragon_seal", 3500, 2, "HE_Tianxia", comps=usable("Seal the edict", "Fermanı mühürle", weather="FoggyRain", flee=0.25, cooldown=11, sound="HE_Sound_Gong"), beauty=30)
WAR_DRUM = item("HE_Albion_Artifact_WarDrum", "Drum of the Avalon Guard", "Avalon Muhafızları'nın Davulu",
                "The old regimental drum, restored with new brass and a fresh skin. When it beats the advance, your people stand in line as one and enemies hear a whole army coming. It must rest for ten days between uses.",
                "Yeni pirinç ve taze deriyle onarılmış eski alay davulu. İlerleme marşını çaldığında halkın tek vücut olarak saf tutar ve düşmanlar bütün bir ordunun geldiğini duyar. Her kullanımdan sonra on gün dinlenmesi gerekir.",
                "war_drum", 3500, 4, "HE_Albion", comps=usable("Beat the advance", "İlerleme marşını çal", flee=0.35, cooldown=10, sound="HE_Sound_Drum"), beauty=15)

# ------------------------------------------------------------------ chains
add(F, Def("HeirsOfEarth.ChainDef", "HE_Chain_Hellas", nation="HE_Hellas", artifact=AEGIS, startKnowledge=60,
           label=T("The Lost Library", "Kayıp Kütüphane"),
           description=T("The library of the colony ship Argo was buried by an earthquake two centuries ago. Find it, and decide who may read it.",
                         "Argo koloni gemisinin kütüphanesi iki yüzyıl önce bir depremle gömüldü. Onu bul ve kimin okuyabileceğine karar ver."),
           startText=T("An old scholar of the league arrives with a surveyor's map and a fever. Before the illness takes him, he wants one thing: to see the lost library of the Argo opened again. He believes he knows where it lies.",
                       "Birliğin yaşlı bir âlimi bir kadastro haritası ve ateşli bir hastalıkla gelir. Hastalık onu alıp götürmeden önce tek bir şey ister: Argo'nun kayıp kütüphanesinin yeniden açıldığını görmek. Nerede olduğunu bildiğine inanıyor."),
           endText=T("The opening of the lost library is now a famous story in Hellas, and the name of your colony is written in its first chapter.",
                     "Kayıp kütüphanenin açılışı artık Hellas'ta ünlü bir hikâye ve koloninin adı onun ilk bölümüne yazılı."),
           steps=[
               step("Deliver", "Supplies for the scholar", "Âlim için malzeme",
                    "The scholar needs medicine for his fever and cloth for copying. Gather 100 cloth and 20 herbal medicine, then deliver them from the Stories page.",
                    "Âlimin ateşi için ilaca, kopya için kumaşa ihtiyacı var. 100 kumaş ve 20 şifalı ot topla, sonra Hikâyeler sayfasından teslim et.",
                    "The fever breaks. The scholar unrolls his map: the old survey can only be read by someone who knows geometry.",
                    "Ateş düşer. Âlim haritasını açar: eski kadastro ancak geometri bilen biri tarafından okunabilir.",
                    things=things(Cloth=100, MedicineHerbal=20)),
               step("Research", "Read the old survey", "Eski kadastroyu oku",
                    "Learn the geometry tradition so your colonists can follow the surveyor's lines to the buried city.",
                    "Kolonistlerinin kadastrocunun çizgilerini gömülü şehre kadar izleyebilmesi için geometri geleneğini öğren.",
                    "The lines meet in the hills. Unfortunately, treasure hunters have been watching your colony.",
                    "Çizgiler tepelerde birleşiyor. Ne yazık ki hazine avcıları kolonini izliyormuş.",
                    project="HE_Hellas_Geometry"),
               step("Raid", "The treasure hunters", "Hazine avcıları",
                    "A band of treasure hunters wants the map for themselves. Drive them off.",
                    "Bir hazine avcısı çetesi haritayı kendileri için istiyor. Onları püskürt.",
                    "The treasure hunters are beaten. Their leader's notes confirm it: the library lies under a ruined temple.",
                    "Hazine avcıları yenildi. Liderlerinin notları bunu doğruluyor: kütüphane yıkık bir tapınağın altında.",
                    points=500),
               step("Site", "The buried temple", "Gömülü tapınak",
                    "Send a caravan to the buried temple marked on the world map, defeat the looters camped there and bring the library scrolls home.",
                    "Dünya haritasında işaretli gömülü tapınağa bir kervan gönder, orada kamp kuran yağmacıları yen ve kütüphane tomarlarını eve getir.",
                    "The scrolls are yours: geometry, medicine, lost plays. And beneath them, wrapped in linen, a bronze aegis with an owl upon it.",
                    "Tomarlar artık senin: geometri, tıp, kayıp oyunlar. Ve altlarında, ketene sarılı, üzerinde bir baykuş olan bronz bir aegis.",
                    siteLayout="Ruin", siteWall="BlocksLimestone", siteProp="HE_Hellas_Column", siteReward=SCROLLS, siteThreat=1.0),
               step("Choice", "Whose library?", "Kimin kütüphanesi?",
                    "The league asks for the scrolls, to copy them in every city. Your colonists would rather keep the aegis that lay among them, and the league will not give it up easily.",
                    "Birlik, tomarları her şehirde kopyalamak için istiyor. Kolonistlerin ise aralarında yatan aegisi saklamayı yeğliyor ve birlik ondan kolay vazgeçmeyecek.",
                    options=[
                        option("Give everything to the league", "Her şeyi birliğe ver",
                               "The league copies the library in every city and honours your colony as its finder.", "Birlik kütüphaneyi her şehirde kopyalar ve kolonini onu bulan olarak onurlandırır.",
                               goodwill=40, knowledge=40, keep=False, rewards=things(Silver=600), takes=things(HE_Hellas_LibraryScrolls=1)),
                        option("Keep the aegis", "Aegisi sakla",
                               "You hand over the scrolls but keep the Owl Aegis. The archons call it a scandal.", "Tomarları teslim edersin ama Baykuş Aegisi'ni saklarsın. Arkonlar buna skandal der.",
                               goodwill=-30, keep=True, takes=things(HE_Hellas_LibraryScrolls=1)),
                    ]),
           ]))

add(F, Def("HeirsOfEarth.ChainDef", "HE_Chain_Tianxia", nation="HE_Tianxia", artifact=DRAGON_SEAL, startKnowledge=60,
           label=T("The Palace Examination", "Saray Sınavı"),
           description=T("The jade seal of the emperor has been stolen. The court has set an examination: whoever returns it passes.",
                         "İmparatorun yeşim mührü çalındı. Saray bir sınav koydu: onu geri getiren sınavı geçer."),
           startText=T("A court eunuch arrives with an imperial notice: the jade seal has vanished from the palace, and Yamato agents are blamed. Any household that recovers it will be honoured above all others. Your colony has been invited to sit this examination.",
                       "Bir saray hadımı imparatorluk duyurusuyla gelir: yeşim mühür saraydan kayboldu ve Yamato ajanları suçlanıyor. Onu geri getiren her hane diğerlerinin üstünde onurlandırılacak. Kolonin bu sınava girmeye davet edildi."),
           endText=T("The tale of the jade seal is told in every tea house of Tianxia, and your colony is the hero of it, or the villain.",
                     "Yeşim mührün hikâyesi Tianxia'nın her çay evinde anlatılıyor ve kolonin bu hikâyenin ya kahramanı ya da kötüsü."),
           steps=[
               step("Deliver", "Gifts for the examiners", "Sınav görevlilerine armağanlar",
                    "No examination begins without proper gifts. Gather 30 gold and 20 jade, then deliver them from the Stories page.",
                    "Hiçbir sınav uygun armağanlar olmadan başlamaz. 30 altın ve 20 yeşim topla, sonra Hikâyeler sayfasından teslim et.",
                    "The examiners are satisfied. The first question: can your household keep a garden worthy of a scholar?",
                    "Görevliler memnun. İlk soru: hanen bir âlime layık bir bahçeye sahip olabilir mi?",
                    things=things(Gold=30, Jade=20)),
               step("Build", "A scholar's garden", "Bir âlim bahçesi",
                    "Build a moon gate in your colony to show the examiners your household's refinement.",
                    "Hanenin inceliğini görevlilere göstermek için kolonine bir ay kapısı inşa et.",
                    "The examiners pass you through the gate with a nod. That night, the thieves' friends come for you.",
                    "Görevliler başlarını sallayarak seni kapıdan geçirir. O gece hırsızların dostları senin için gelir.",
                    building="HE_Tianxia_MoonGate"),
               step("Raid", "The night attack", "Gece baskını",
                    "Yamato agents want to stop your household before it finds the seal. Defeat them.",
                    "Yamato ajanları hanen mührü bulmadan onu durdurmak istiyor. Onları yen.",
                    "One captured agent talks: the seal is hidden in an abandoned summer palace.",
                    "Yakalanan bir ajan konuşur: mühür terk edilmiş bir yazlık sarayda saklı.",
                    enemy="HE_Yamato", points=600),
               step("Site", "The summer palace", "Yazlık saray",
                    "Send a caravan to the summer palace marked on the world map, defeat its guards and bring the jade seal home.",
                    "Dünya haritasında işaretli yazlık saraya bir kervan gönder, muhafızlarını yen ve yeşim mührü eve getir.",
                    "The seal is in your hands, cracked but whole. Holding it, you feel the weight of an empire.",
                    "Mühür elinde, çatlak ama bütün. Onu tutarken bir imparatorluğun ağırlığını hissediyorsun.",
                    enemy="HE_Yamato", siteLayout="Hall", siteWall="BlocksMarble", siteProp="HE_Tianxia_Vase", siteReward=JADE_SEAL, siteThreat=1.0),
               step("Choice", "The last question", "Son soru",
                    "The court waits. You can return the seal to the emperor and pass the examination with honour, or mend it with gold and keep it, as rebels once did.",
                    "Saray bekliyor. Mührü imparatora geri verip sınavı onurla geçebilir ya da onu altınla onarıp eskiden asilerin yaptığı gibi saklayabilirsin.",
                    options=[
                        option("Return the seal", "Mührü geri ver",
                               "The emperor himself reads your name aloud. Your household has passed the palace examination.", "İmparator adını bizzat yüksek sesle okur. Hanen saray sınavını geçti.",
                               goodwill=40, knowledge=40, keep=False, rewards=things(Silver=500, Gold=20), takes=things(HE_Tianxia_JadeSeal=1)),
                        option("Keep the seal", "Mührü sakla",
                               "Mended with gold, the seal is yours. The court declares your household rebels.", "Altınla onarılan mühür artık senin. Saray haneni asi ilan eder.",
                               goodwill=-30, keep=True, takes=things(HE_Tianxia_JadeSeal=1)),
                    ]),
           ]))

add(F, Def("HeirsOfEarth.ChainDef", "HE_Chain_Albion", nation="HE_Albion", artifact=WAR_DRUM, startKnowledge=60,
           label=T("Iron Revolution", "Demir Devrimi"),
           description=T("Albion's first engine works were burned by Roman saboteurs long ago. Rebuild the engine, and decide whose drum it marches to.",
                         "Albion'un ilk makine atölyeleri uzun zaman önce Romalı sabotajcılar tarafından yakıldı. Makineyi yeniden inşa et ve kimin davuluna göre yürüyeceğine karar ver."),
           startText=T("A retired engineer of the commonwealth arrives with a roll of drawings. The old engine works of Avalon, he says, still hold the patterns of the first steam engine and the drum of the regiment that guarded them. Parliament would pay a fortune for both.",
                       "Topluluğun emekli bir mühendisi bir rulo çizimle gelir. Avalon'un eski makine atölyelerinde, der, hâlâ ilk buhar makinesinin kalıpları ve onları koruyan alayın davulu duruyor. Parlamento ikisi için de bir servet öder."),
           endText=T("Albion's newspapers call it the second iron revolution, and your colony is on every front page.",
                     "Albion gazeteleri buna ikinci demir devrimi diyor ve kolonin her ön sayfada."),
           steps=[
               step("Deliver", "Iron and parts", "Demir ve parçalar",
                    "The engineer needs material to rebuild the old patterns. Gather 300 steel and 8 components, then deliver them from the Stories page.",
                    "Mühendisin eski kalıpları yeniden yapmak için malzemeye ihtiyacı var. 300 çelik ve 8 parça topla, sonra Hikâyeler sayfasından teslim et.",
                    "The patterns are cast. Now your colony must learn how the engine works.",
                    "Kalıplar döküldü. Şimdi kolonin makinenin nasıl çalıştığını öğrenmeli.",
                    things=things(Steel=300, ComponentIndustrial=8)),
               step("Research", "The steam engine", "Buhar makinesi",
                    "Research the steam engine so your engineers can understand the old drawings.",
                    "Mühendislerinin eski çizimleri anlayabilmesi için buhar makinesini araştır.",
                    "The drawings make sense at last. Word has reached Nova Roma, and its agents are on their way.",
                    "Çizimler sonunda anlam kazandı. Haber Nova Roma'ya ulaştı ve ajanları yolda.",
                    project="HE_Albion_SteamEngine"),
               step("Raid", "Roman saboteurs", "Romalı sabotajcılar",
                    "Nova Roma will not let Albion grow stronger. Its saboteurs are coming to burn your workshops. Stop them.",
                    "Nova Roma, Albion'un güçlenmesine izin vermeyecek. Sabotajcıları atölyelerini yakmaya geliyor. Onları durdur.",
                    "The saboteurs are beaten. One of them carried a map of the old engine works, marked for burning.",
                    "Sabotajcılar yenildi. İçlerinden biri, yakılmak üzere işaretlenmiş eski makine atölyelerinin bir haritasını taşıyordu.",
                    enemy="HE_Roma", points=800),
               step("Site", "The old engine works", "Eski makine atölyeleri",
                    "Send a caravan to the old engine works marked on the world map, defeat the Roman guards and bring the regimental drum home.",
                    "Dünya haritasında işaretli eski makine atölyelerine bir kervan gönder, Romalı muhafızları yen ve alay davulunu eve getir.",
                    "Among the rusted machines you find the drum of the Avalon Guard, dented but unbroken.",
                    "Paslı makinelerin arasında Avalon Muhafızları'nın davulunu buluyorsun; ezik ama kırılmamış.",
                    enemy="HE_Roma", siteLayout="Ring", siteWall="BlocksGranite", siteProp="HE_Albion_SteamEngine", siteReward=OLD_DRUM, siteThreat=1.0),
               step("Choice", "The drum's master", "Davulun efendisi",
                    "Parliament wants the drum for the national museum. Your colonists want to restore it and march to it themselves.",
                    "Parlamento davulu ulusal müze için istiyor. Kolonistlerin ise onu onarıp kendileri onunla yürümek istiyor.",
                    options=[
                        option("Give it to Parliament", "Parlamentoya ver",
                               "Parliament votes your colony its thanks and a handsome purse.", "Parlamento kolonine teşekkürünü ve dolgun bir kese oylar.",
                               goodwill=40, knowledge=40, keep=False, rewards=things(Silver=500, ComponentIndustrial=6), takes=things(HE_Albion_DentedDrum=1)),
                        option("Restore it and keep it", "Onar ve sakla",
                               "Your smiths restore the drum. Parliament calls it theft of national property.", "Demircilerin davulu onarır. Parlamento buna ulusal malın çalınması der.",
                               goodwill=-30, keep=True, takes=things(HE_Albion_DentedDrum=1)),
                    ]),
           ]))

# ------------------------------------------------------------------ capstone traditions that open when the story ends
research("Hellas", "GoldenAge", "golden age", "altın çağ",
         "With the library opened, the league enters an age of plays, cures and arguments that will be remembered for centuries.",
         "Kütüphane açıldığından beri birlik, yüzyıllarca hatırlanacak oyunlar, tedaviler ve tartışmalarla dolu bir çağa giriyor.",
         1800, "Medieval", 1, 3, prereqs=["HE_Hellas_Theatre"], knowledge=50, tradition=True, chain="HE_Chain_Hellas",
         stats=[("GlobalLearningFactor", 0.05, 1, "Colonists"), ("SocialImpact", 0.05, 1, "Colonists"), ("MedicalTendQuality", 0.05, 1, "Colonists")],
         effect=T("Colonists learn 5% faster and gain +5% social impact and +5% tend quality.",
                  "Kolonistler %5 daha hızlı öğrenir, +%5 sosyal etki ve +%5 tedavi kalitesi kazanır."))
research("Tianxia", "Harmony", "harmonious realm", "uyumlu ülke",
         "Heaven's seal is where it belongs, and every household works in calm order.",
         "Göğün mührü ait olduğu yerde ve her hane sakin bir düzen içinde çalışıyor.",
         1800, "Medieval", 1, 3, prereqs=["HE_Tianxia_FireArrows"], knowledge=50, tradition=True, chain="HE_Chain_Tianxia",
         stats=[("WorkSpeedGlobal", 0, 1.03, "Colonists"), ("MentalBreakThreshold", -0.03, 1, "Colonists")],
         effect=T("Colonists work 3% faster and their mental break threshold drops by 3%.",
                  "Kolonistler %3 daha hızlı çalışır ve zihinsel çöküş eşikleri %3 düşer."))
research("Albion", "Workshop", "workshop of the world", "dünyanın atölyesi",
         "The engines of Albion turn day and night, and the whole colony keeps time with them.",
         "Albion'un makineleri gece gündüz döner ve bütün koloni onlarla aynı tempoyu tutar.",
         1900, "Industrial", 1, 3, prereqs=["HE_Albion_Drill"], knowledge=50, tradition=True, chain="HE_Chain_Albion",
         stats=[("WorkSpeedGlobal", 0, 1.04, "Colonists"), ("ShootingAccuracyPawn", 1, 1, "Colonists")],
         effect=T("Colonists work 4% faster and gain +1 shooting accuracy.",
                  "Kolonistler %4 daha hızlı çalışır ve +1 atış isabeti kazanır."))
